 static void login(Client c)throws Exception{Field u=Client.class.getDeclaredField("myUsername");u.setAccessible(true);u.set(c,"final69qa");c.setPassword("FinalLocalAudit69");c.enqueueGameAction(()->c.login("final69qa","FinalLocalAudit69",false));waitFor(()->Client.loggedIn,"Local fixture login");waitFor(()->{try{return(int)get(c,"loadingStage")==2;}catch(Exception e){return false;}},"World map");}
